import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十八卦 睽 火泽睽 离上兑下","description":"周易 - 第三十八卦 睽 火泽睽 离上兑下","frontmatter":{"title":"第三十八卦 睽 火泽睽 离上兑下","description":"周易 - 第三十八卦 睽 火泽睽 离上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/039.md","filePath":"zh/classics/zhouyi/039.md"}'),l={name:"zh/classics/zhouyi/039.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="睽" tabindex="-1">睽 <a class="header-anchor" href="#睽" aria-label="Permalink to “睽”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>小事吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>睽，火动而上，泽动而下；二女同居，其志不同行；说而丽乎明，柔进而上行，得中而应乎刚；是以小事吉。天地睽，而其事同也；男女睽，而其志通也；万物睽，而其事 类也；睽之时用大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>上火下泽，睽；君子以同而异。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>悔亡，丧马勿逐，自复；见恶人无咎。象 曰：见恶人，以辟咎也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>遇主于巷，无咎。象曰：遇主于巷，未失道也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>见舆曳，其牛掣，其人天且劓，无初有终。象曰：见舆曳，位不当也。无初有终，遇刚也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>睽孤，遇元夫，交孚，厉无咎。象曰：交孚无咎，志行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>悔亡，厥宗噬肤，往何咎。象曰：厥宗噬肤，往有庆也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。象曰：遇雨之吉，群疑亡也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
